/**
 * Icons as the pen draws them: lucide glyphs flattened to filled outlines on a
 * 14 x 14 box (exported from docs/design/miroir.pen). Using the export rather
 * than today's lucide-static keeps stroke weight and geometry identical
 * (lucide has since moved some lines, e.g. "menu").
 */

defined( 'ABSPATH' ) || exit;

/**
 * Inline SVG icon. Colour follows currentColor, as pen icons take the text token colour.
 *
 * @param string $name  Lucide icon name.
 * @param int    $size  Rendered width and height in px.
 * @param string $class Extra class.
 */
function miroir_icon( $name, $size = 24, $class = '' ) {
	if ( 'whatsapp' === $name ) {
		static $whatsapp = null;
		if ( null === $whatsapp ) {
			$whatsapp = file_get_contents( MIROIR_THEME_DIR . '/assets/images/whatsapp.svg' );
		}
		return str_replace( array( 'width="24" height="24"', 'class="icon icon-whatsapp"' ), array( 'width="' . absint( $size ) . '" height="' . absint( $size ) . '"', 'class="icon icon-whatsapp ' . esc_attr( $class ) . '"' ), $whatsapp );
	}
	if ( 'bag' === $name ) {
		static $bag = null;
		if ( null === $bag ) {
			$bag = file_get_contents( MIROIR_THEME_DIR . '/assets/images/bag.svg' );
		}
		return str_replace( array( 'width="24" height="28"', 'class="icon icon-bag"' ), array( 'width="' . absint( $size ) . '" height="' . absint( round( $size * 28 / 24 ) ) . '"', 'class="icon icon-bag ' . esc_attr( $class ) . '"' ), $bag );
	}
